return items.map(item => {

  const html = item.json.body || "";

  // Extract emails
  const matches = html.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
  );

  // Remove duplicates
  const emails = [...new Set(matches || [])];

  item.json.extractedEmails = emails;

  // Choose first email
  item.json.recruiter_email = emails[0] || "";

  return item;
});
